-- Migration 035: Migrate style_presets to creative_concepts
-- Feature: 031 - Creative Concepts Migration
-- Created: 2026-02-07
-- Description: Renames style_presets to creative_concepts, enriches schema with
--   new columns (description, icon, niche, works_for_niches, prompt_template_json,
--   example_images), and seeds 88 creative concept rows from Alvo Bot.

BEGIN;

-- 1. Rename table
ALTER TABLE style_presets RENAME TO creative_concepts;

-- 2. Drop columns no longer needed
ALTER TABLE creative_concepts DROP COLUMN IF EXISTS preset_type;

-- 3. Add new columns
ALTER TABLE creative_concepts ADD COLUMN IF NOT EXISTS description TEXT;
ALTER TABLE creative_concepts ADD COLUMN IF NOT EXISTS prompt_template TEXT;
ALTER TABLE creative_concepts ADD COLUMN IF NOT EXISTS prompt_template_json JSONB;
ALTER TABLE creative_concepts ADD COLUMN IF NOT EXISTS template_variables JSONB;
ALTER TABLE creative_concepts ADD COLUMN IF NOT EXISTS icon VARCHAR(10);
ALTER TABLE creative_concepts ADD COLUMN IF NOT EXISTS niche VARCHAR(50);
ALTER TABLE creative_concepts ADD COLUMN IF NOT EXISTS works_for_niches JSONB;
ALTER TABLE creative_concepts ADD COLUMN IF NOT EXISTS example_images JSONB;
ALTER TABLE creative_concepts ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ;

-- 4. Delete all existing rows (replacing with full set of 88 concepts)
DELETE FROM creative_concepts;

-- 5. Insert all 88 creative concepts
INSERT INTO creative_concepts (
    id, name, name_pt, slug, description, prompt_modifier, 
    prompt_template_json, icon, category, niche, works_for_niches, 
    example_images, sort_order, is_active
)
VALUES
    ('04ac1bcb-908b-40c5-9b87-32e692e1c00d', 'Simulador / Calculadora UI', 'Simulador / Calculadora UI', 'simulator-ui', 'Interface de app com sliders, botões, campos. O UI É o criativo - parece screenshot de app real.', 'Fintech app UI showing a calculator or simulator interface. Clean, modern app design with input fields, sliders, or value selection buttons. The UI IS the creative - it looks like a real app screenshot that invites interaction. Professional design, high legibility, no text overlap.', '{"concept": "simulator-ui", "composition": {"style": "modern-fintech", "layout": "centered-card", "main_element": "App UI with interactive controls"}, "requirements": ["input fields or sliders", "value buttons", "clear CTA", "app-like design"], "visual_description": "Clean fintech app interface with calculator/simulator"}'::jsonb, '📱', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 1, true),
    ('d0524725-bff5-41e9-afed-37e6e32ed0b9', 'Tipografia Dominante', 'Tipografia Dominante', 'typography', 'Headline ENORME, sem fotos, fundo sólido. Pattern interrupt - visualmente diferente de tudo no feed.', 'Bold, dominant typography design. A massive headline that takes up the entire creative space. No photos, just powerful text on a solid or gradient background. Pattern interrupt style - visually different from everything in the feed. Extra-large text, high contrast, minimal elements.', '{"concept": "typography", "composition": {"layout": "full-bleed", "background": "solid-or-gradient", "main_element": "Giant text headline"}, "requirements": ["extra-large text", "no photos", "high contrast", "pattern interrupt"], "visual_description": "Massive headline dominating the creative"}'::jsonb, '🔤', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 2, true),
    ('b2768114-e2ce-4f72-a634-5cde37a59d90', 'Depoimento / Prova Social', 'Depoimento / Prova Social', 'testimonial', 'Cards de review estilo app store. Foto da pessoa, citação grande, estrelas ou badge de confiança.', 'Testimonial-style card with a quote from a real-looking person. Photo of the person, their quote in large readable text, star rating or trust badge. Clean card UI floating over a subtle background. Feels like a real app review. Authentic, trustworthy design.', '{"concept": "testimonial", "composition": {"layout": "floating-card", "elements": ["person_photo", "quote_text", "star_rating", "trust_badge"], "main_element": "Testimonial card"}, "requirements": ["real-looking person", "readable quote", "trust indicators", "card design"], "visual_description": "Review card with person photo and quote"}'::jsonb, '⭐', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 3, true),
    ('6a5685a5-665b-4fb8-9197-55123b762ff4', 'Antes / Depois', 'Antes / Depois', 'before-after', 'Split-screen com contraste claro. Lado esquerdo mostra problema, lado direito mostra solução.', 'Split-screen or side-by-side composition showing a dramatic before/after transformation. Left side shows the before state (struggle, problem, pain point), right side shows the after state (success, solution, achievement). Clear visual contrast, obvious improvement. Professional layout.', '{"concept": "before-after", "composition": {"layout": "split-screen", "left_side": "before_state", "right_side": "after_state", "main_element": "Side-by-side comparison"}, "requirements": ["clear contrast", "obvious transformation", "labeled sections", "professional"], "visual_description": "Split-screen transformation comparison"}'::jsonb, '↔️', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 4, true),
    ('cda41059-576c-400f-9302-6a5cc25f5722', 'Hook de Pergunta', 'Hook de Pergunta', 'question-hook', 'Pergunta ENORME que fala com a dor do público. A pergunta É o criativo - mínimo de elementos.', 'The entire creative is dominated by a single large, provocative question that speaks directly to the viewer pain point. The question is typographically massive - it IS the creative. Minimal supporting elements, maximum text impact. Question mark prominent.', '{"concept": "question-hook", "composition": {"style": "provocative", "layout": "text-dominant", "main_element": "Large question text"}, "requirements": ["large question text", "speaks to pain point", "minimal elements", "prominent question mark"], "visual_description": "Giant provocative question"}'::jsonb, '❓', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 5, true),
    ('ceb2c593-2d58-4bb7-84ef-079be6e9ad3e', 'Comparação / Versus', 'Comparação / Versus', 'comparison', 'Tradicional vs Nosso. Checkmarks vs X. Simplifica decisão para o viewer.', 'Side-by-side comparison layout: Traditional way vs Our way. Clear visual contrast - one side negative/complicated with X marks, the other positive/simple with checkmarks. Simplifies decision for the viewer. Clean professional layout.', '{"concept": "comparison", "composition": {"layout": "versus-table", "left_column": "traditional_way", "main_element": "Two-column comparison", "right_column": "our_way"}, "requirements": ["X vs checkmark icons", "clear labeling", "obvious winner", "professional"], "visual_description": "Versus comparison with checkmarks"}'::jsonb, '⚖️', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 6, true),
    ('3d0a9909-76a2-423a-a8bb-c7a7fbe14bce', 'Native / UGC-style', 'Native / UGC-style', 'native-ugc', 'Parece post orgânico, notificação de celular, ou chat. Radicalmente diferente de UI polido.', 'The ad looks like an organic post or native phone UI. Screenshot of a conversation, phone notification, or social media post style. Radically different from polished UI = real diversity. Authentic, casual, user-generated feel.', '{"concept": "native-ugc", "composition": {"style": "user-generated", "layout": "phone-screenshot", "main_element": "Native phone UI element"}, "requirements": ["looks organic", "phone UI elements", "casual feel", "not polished"], "visual_description": "Organic-looking native content"}'::jsonb, '📲', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 7, true),
    ('82f7ec0e-d9c0-40e7-919a-54caa6272981', 'Banner / Professional Design', 'Banner / Professional Design', 'banner-professional', 'Banner de anúncio profissional com CTA claro. Design de qualidade de marca.', 'Professional advertisement banner design. Clean, polished layout that looks like it was made by a professional designer. Clear CTA button, professional elements, brand-quality design. High production value, attention to detail.', '{"concept": "banner-professional", "composition": {"style": "brand-quality", "layout": "banner-format", "main_element": "Polished banner layout"}, "requirements": ["clear CTA", "professional polish", "brand quality", "attention to detail"], "visual_description": "Professional ad banner design"}'::jsonb, '🎨', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 8, true),
    ('3aefaf0b-2062-45c8-ba7e-2417cf312b0b', 'Editorial / Estilo Artigo', 'Editorial / Estilo Artigo', 'editorial-article', 'Imagem que simula manchete e layout de portal de notícias.', 'Editorial news-style layout with a thumbnail photo and a bold headline. Clean white background, serif or clean sans-serif typography, layout that resembles a news portal article card. Native, credible, non-ad feel. Use serif headline (Playfair Display/Georgia) with clean sans-serif subhead (Inter/Source Sans).', '{"concept": "editorial-article", "typography": {"font_style": "Serif headline (Playfair/Georgia) + clean sans-serif subhead (Inter/Source Sans)"}, "composition": {"style": "clean-editorial", "layout": "news-card", "main_element": "headline + photo card"}, "requirements": ["headline", "thumbnail image", "white background", "portal-like layout", "serif headline"], "visual_description": "News portal headline + thumbnail layout"}'::jsonb, '📰', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 9, true),
    ('45d6d78b-5334-4520-aa94-b1a38981c7fa', 'WikiHow / Tutorial Ilustrado', 'WikiHow / Tutorial Ilustrado', 'wikihow-tutorial', 'Ilustração didática passo a passo com setas e numeração.', 'WikiHow-style tutorial illustration with flat, simple drawings, step numbers, and arrows. Educational, clear, and instantly recognizable as a how-to guide. Minimal palette, clean line art.', '{"concept": "wikihow-tutorial", "composition": {"style": "flat-illustration", "layout": "instructional-grid", "main_element": "illustrated steps"}, "requirements": ["step numbers", "arrows", "flat drawings", "instructional look"], "visual_description": "Step-by-step illustrated tutorial"}'::jsonb, '🧭', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 10, true),
    ('3393c42d-90b8-4d6f-a2da-e34665811a52', 'Mockup de Jornal / Revista', 'Mockup de Jornal / Revista', 'newspaper-mockup', 'Página impressa de jornal/revista com matéria sobre o produto.', 'Printed newspaper or magazine mockup showing a full page article. Visible paper texture, columns, headline, and photo. Looks like a physical newspaper or magazine page being held or laid on a table. Use classic newspaper serif fonts (e.g., Times New Roman, Newsprint).', '{"concept": "newspaper-mockup", "typography": {"font_style": "Classic newspaper serif (Times New Roman/Newsprint)"}, "composition": {"style": "print-editorial", "layout": "print-columns", "main_element": "newspaper page"}, "requirements": ["columns", "headline", "paper texture", "print layout", "newspaper serif"], "visual_description": "Physical newspaper page with article"}'::jsonb, '🗞️', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 11, true),
    ('004411a8-f68e-4e3a-a040-603c71bd5a19', 'Screenshot de Chat', 'Screenshot de Chat', 'chat-screenshot', 'Simula conversa no WhatsApp/iMessage com recomendação.', 'Chat screenshot lookalike with two people discussing and recommending the product. WhatsApp/iMessage/Instagram Inbox style, Mobile UI bubbles, timestamps, casual tone. Feels like a real phone conversation screenshot.', '{"concept": "chat-screenshot", "composition": {"style": "native-ui", "layout": "phone-screenshot", "main_element": "chat bubbles"}, "requirements": ["chat bubbles", "timestamps", "mobile UI", "casual tone"], "visual_description": "Mobile chat conversation screenshot"}'::jsonb, '💬', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 12, true),
    ('0ff26f4b-ae66-4b73-8f5d-95aaa1f238cb', 'Screenshot de Comentários', 'Screenshot de Comentários', 'comments-screenshot', 'Print de comentários/reviews em redes sociais elogiando o produto.', 'Screenshot-style layout showing social media comments or reviews praising the product. Native UI elements, avatars, like/reply indicators. Looks like real social proof.', '{"concept": "comments-screenshot", "composition": {"style": "native-ui", "layout": "social-screenshot", "main_element": "comments list"}, "requirements": ["comment avatars", "like/reply UI", "stacked comments", "authentic look"], "visual_description": "Social media comments screenshot"}'::jsonb, '🗨️', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 13, true),
    ('6bdbfbf4-4a16-4b2c-b1c8-fe71ff803fd6', 'Meme / Humor Nativo', 'Meme / Humor Nativo', 'meme-native', 'Formato de meme popular adaptado ao produto.', 'Classic meme template adapted to the product. Familiar layout, humorous contrast, high shareability. Keep it native to meme culture, minimal branding.', '{"concept": "meme-native", "composition": {"style": "internet-native", "layout": "meme-template", "main_element": "meme panels"}, "requirements": ["recognizable meme format", "clear punchline", "minimal branding"], "visual_description": "Recognizable meme template"}'::jsonb, '😂', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 14, true),
    ('a081db1b-1df2-4414-93de-10f170849923', 'Print de Resultado / Dashboard', 'Print de Resultado / Dashboard', 'dashboard-proof', 'Screenshot de analytics, extrato ou painel de resultados.', 'Dashboard or analytics screenshot showing results, metrics, or performance. Clean charts, numbers, KPIs. Looks like a real app/dashboard capture used as proof.', '{"concept": "dashboard-proof", "composition": {"style": "software-ui", "layout": "dashboard-grid", "main_element": "charts and KPIs"}, "requirements": ["charts", "metrics", "clean UI", "realistic dashboard"], "visual_description": "Analytics dashboard screenshot"}'::jsonb, '📈', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 15, true),
    ('ee403843-3224-4119-b650-a71c1237f847', 'UGC Photo / Selfie', 'UGC Photo / Selfie', 'ugc-selfie', 'Foto realista e amadora, estilo cliente real.', 'Casual, amateur-looking photo or selfie of a real person using the product. Natural lighting, imperfect framing, authentic feel. Looks like customer-generated content.', '{"concept": "ugc-selfie", "composition": {"style": "authentic-ugc", "layout": "casual-photo", "main_element": "person + product"}, "requirements": ["natural lighting", "imperfect framing", "real person", "authentic vibe"], "visual_description": "Amateur user photo"}'::jsonb, '🤳', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 16, true),
    ('8f7aec97-62fa-4f7f-95ea-4b0b4c1e831a', 'Listicle Visual', 'Listicle Visual', 'listicle-visual', 'Imagem com lista numerada de razões/benefícios.', 'Visual listicle layout with numbered items and concise benefit statements. Looks like the cover of a listicle article. Bold numbers, clear hierarchy, easy scanning. Use a condensed display font for numbers (e.g., Bebas Neue/Anton) and a clean sans-serif for body (e.g., Inter/Source Sans).', '{"concept": "listicle-visual", "typography": {"font_style": "Numbers in condensed display (Bebas Neue/Anton), body in clean sans-serif (Inter/Source Sans)"}, "composition": {"style": "headline-driven", "layout": "stacked-list", "main_element": "numbered list"}, "requirements": ["numbered items", "clear hierarchy", "scannable layout", "distinct number font", "clean body font"], "visual_description": "Numbered benefits list"}'::jsonb, '🔢', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 17, true),
    ('ba61cb4c-1cf3-4372-a298-031449fbd4ee', 'Post de Rede Social', 'Post de Rede Social', 'social-post-screenshot', 'Simula um post orgânico (Instagram/Twitter/X/TikTok).', 'Social post screenshot with full interface: profile name, avatar, like/comment counts, and caption. Looks like a real organic post shared by someone.', '{"concept": "social-post-screenshot", "composition": {"style": "native-ui", "layout": "social-feed", "main_element": "post UI card"}, "requirements": ["profile header", "like/comment UI", "caption text", "native look"], "visual_description": "Organic social post screenshot"}'::jsonb, '📸', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 18, true),
    ('d4141e88-706c-4644-be01-b6e397923712', 'Post-it Note', 'Post-it Note', 'post-it-note', 'Anotação em post-it com benefício central.', 'Handwritten post-it note photographed or simulated. Short benefit statement written in marker. Slightly imperfect, authentic, and attention-grabbing.', '{"concept": "post-it-note", "composition": {"style": "handwritten", "layout": "centered", "main_element": "post-it note"}, "requirements": ["handwritten text", "sticky note look", "minimal design", "authentic feel"], "visual_description": "Handwritten sticky note"}'::jsonb, '📝', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 19, true),
    ('31f02f26-02b9-4a07-933e-23d9f9ea6ba7', 'Screenshot do Notes App', 'Screenshot do Notes App', 'notes-app-screenshot', 'Texto no app de notas com visual nativo mobile.', 'Notes app screenshot with text block, simple typography, and native mobile UI. Feels like a personal note shared by a friend.', '{"concept": "notes-app-screenshot", "composition": {"style": "native-ui", "layout": "phone-screenshot", "main_element": "notes text"}, "requirements": ["notes app UI", "text block", "minimal styling", "native look"], "visual_description": "Mobile notes app screenshot"}'::jsonb, '🗒️', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 20, true),
    ('a4e85d8f-18aa-4c28-a5a6-8933ff7bfe16', 'Screenshot de Tweet/X', 'Screenshot de Tweet/X', 'tweet-screenshot', 'Print de tweet com prova social e engajamento.', 'Tweet/X screenshot with handle, text, and engagement metrics. Looks like a real post. High native credibility and social proof.', '{"concept": "tweet-screenshot", "composition": {"style": "native-ui", "layout": "social-card", "main_element": "tweet card"}, "requirements": ["handle + avatar", "tweet text", "engagement counts", "native look"], "visual_description": "Tweet/X post screenshot"}'::jsonb, '🐦', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 21, true),
    ('e6e8088c-871c-44dc-a5a6-be0d17a0aeb4', 'Whiteboard / Nota Manuscrita', 'Whiteboard / Nota Manuscrita', 'whiteboard-note', 'Texto escrito à mão em quadro branco ou papel ou post-it.', 'Handwritten note on a whiteboard or paper or post-it. Imperfect marker strokes, casual look. Communicates authenticity and personal explanation.', '{"concept": "whiteboard-note", "composition": {"style": "handmade", "layout": "centered", "main_element": "handwritten text"}, "requirements": ["handwritten text", "whiteboard or paper texture", "imperfect strokes"], "visual_description": "Handwritten note on whiteboard"}'::jsonb, '🧾', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 22, true),
    ('ce1801ec-36bc-445a-908b-7a4ff4408759', 'Notificação / Push', 'Notificação / Push', 'push-notification', 'Imagem que simula notificação de celular.', 'Phone push notification style with app icon and short message. Looks like a real system notification floating over blurred background.', '{"concept": "push-notification", "composition": {"style": "native-ui", "layout": "overlay", "main_element": "notification bubble"}, "requirements": ["app icon", "short message", "notification bubble", "native look"], "visual_description": "Mobile push notification bubble"}'::jsonb, '📳', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 23, true),
    ('ada0af5f-72f8-4571-953a-3eaa04c9afab', 'Problema → Solução', 'Problema → Solução', 'fin-problem-solution', 'Visual story mostrando problema sendo resolvido pelo produto.', 'Visual storytelling showing a financial problem being solved. Left side or first part shows the struggle (bills, stress, denied credit), right side shows the solution (approval, relief, money received). Emotional journey from pain to relief.', '{"concept": "problem-solution", "elements": ["struggle_visual", "solution_visual", "transformation"], "visual_flow": "pain-to-relief"}'::jsonb, '📖', 'narrativa', 'financial', '["financial"]'::jsonb, NULL, 101, true),
    ('a49b534f-68cb-47e8-8bfa-84da537d4599', 'Antes / Depois Financeiro', 'Antes / Depois Financeiro', 'fin-before-after', 'Transformação clara da situação financeira.', 'Dramatic before/after showing financial transformation. Before: empty wallet, stress, denied applications. After: full wallet, peace of mind, approved status. Clear visual contrast emphasizing the positive change.', '{"concept": "before-after", "contrast": "high", "elements": ["financial_stress", "financial_relief"]}'::jsonb, '🔄', 'narrativa', 'financial', '["financial"]'::jsonb, NULL, 102, true),
    ('b5ac03ae-3ea4-4da5-a0f4-789aae1185bf', 'Jornada do Cliente', 'Jornada do Cliente', 'fin-journey', 'Passos visuais da jornada: solicitar → aprovação → dinheiro na conta.', 'Step-by-step customer journey visualization. Step 1: Application (phone/form). Step 2: Approval (checkmark/confirmation). Step 3: Money received (bank account/cash). Clean numbered steps, progress feeling.', '{"steps": 3, "concept": "journey", "elements": ["application", "approval", "money_received"]}'::jsonb, '🚶', 'narrativa', 'financial', '["financial"]'::jsonb, NULL, 103, true),
    ('3d05c843-1aac-4227-867c-1bb1503746e7', 'Lifestyle Aspiracional', 'Lifestyle Aspiracional', 'fin-lifestyle', 'Pessoa vivendo bem após resolver situação financeira.', 'Aspirational lifestyle imagery showing person enjoying life after financial success. Happy family, new purchases, peace of mind. Not flashy luxury, but comfortable, achievable lifestyle. Relatable aspiration.', '{"mood": "aspirational-achievable", "concept": "lifestyle", "elements": ["happy_person", "comfortable_setting", "achievement_feel"]}'::jsonb, '🏠', 'narrativa', 'financial', '["financial"]'::jsonb, NULL, 104, true),
    ('2649fbbe-1699-439e-96f2-7b3f28100775', 'Ugly Ad / Lo-Fi', 'Ugly Ad / Lo-Fi', 'ugly-ad', 'Design intencionalmente amador: handwritten notes, notepad, marker text, MS Paint style. Pattern interrupt radical que destoa de tudo no feed.', 'Intentionally amateur, low-fi design that looks handmade. Handwritten text on notebook paper, marker drawings, casual snapshots. The aesthetic is deliberately unpolished - like someone quickly jotted down a note or drew something by hand. No professional design elements. Raw, authentic, human imperfection. This ugly style stops scrolls because it is radically different from polished ads.', '{"avoid": ["professional design", "clean typography", "stock photos", "gradients"], "concept": "ugly-ad", "composition": {"style": "intentionally-amateur", "layout": "casual-snapshot", "main_element": "Handwritten text or simple drawing"}, "requirements": ["handwritten text", "notebook/paper texture", "marker or pen aesthetic", "no polish", "pattern interrupt"], "visual_description": "Handwritten note or amateur drawing style"}'::jsonb, '✏️', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 109, true),
    ('d0dfec21-9927-441d-960e-afe044cd8817', 'Nativo / Editorial', 'Nativo / Editorial', 'news-article', 'Estilo de artigo de notícia/blog com foto + headline chamativo. Simula link de portal que apareceria organicamente no feed. Formato advertorial.', 'News article or blog post thumbnail style. Clean layout with a compelling photo and bold headline text. Looks like an organic content link from a news portal or blog. White or light background, clean sans-serif or serif typography, thumbnail + headline layout reminiscent of news sites. Include a subtle source attribution and READ MORE call-to-action. Editorial credibility through design.', '{"concept": "news-article", "elements": ["compelling_photo", "bold_headline", "source_name", "cta_button"], "composition": {"style": "editorial-native", "layout": "thumbnail-headline", "main_element": "Photo with headline overlay"}, "requirements": ["news-style headline", "source attribution", "READ MORE CTA", "clean typography", "credible layout"], "visual_description": "News portal thumbnail with headline"}'::jsonb, '📰', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 110, true),
    ('3fa06cf2-6250-4eb0-b1de-aecda0a984c4', 'Diagrama Científico', 'Diagrama Científico', 'scientific-diagram', 'Ilustração médica/anatômica com círculo de destaque sobre foto real. Credibilidade visual instantânea através de elementos científicos.', 'Scientific or medical illustration overlay on a real photo. A circular callout or diagram highlighting a specific body part, organ, or mechanism. The diagram element should look like it is from a medical textbook or scientific journal. Combine real photography with educational illustration elements. Professional, credible, authoritative medical aesthetic.', '{"concept": "scientific-diagram", "elements": ["body_photo", "diagram_overlay", "label_text", "highlight_circle"], "composition": {"style": "medical-educational", "layout": "photo-with-overlay", "main_element": "Anatomical diagram on photo"}, "requirements": ["anatomical illustration", "circular callout", "real photo background", "scientific credibility", "clean lines"], "visual_description": "Medical illustration with circular highlight"}'::jsonb, '🔬', 'universal', 'generic', '["generic","health","financial"]'::jsonb, NULL, 111, true),
    ('df9fdaa1-e4cb-424a-a4e2-b2d4022d25fa', 'Texto no Corpo', 'Texto no Corpo', 'body-text', 'Texto escrito diretamente na pele, corpo ou produto. Impossível ignorar - humanos notam corpos primeiro, texto no corpo se torna simbólico.', 'Large text written directly on human skin, body part, or product surface. The body fills most of the frame. Text appears as if tattooed, stamped, or written with marker on the skin or product. Minimal additional design elements. The human body commands attention, and text on it becomes symbolic and impossible to ignore. Bold, readable typography.', '{"concept": "body-text", "psychology": "embodied-attention-effect", "composition": {"style": "embodied-text", "layout": "body-fills-frame", "main_element": "Body part with text overlay"}, "requirements": ["large body part in frame", "text on skin/product", "minimal elements", "bold readable text", "attention-commanding"], "visual_description": "Text written on body or product"}'::jsonb, '🖐️', 'universal', 'generic', '["generic","health","ecommerce","financial"]'::jsonb, NULL, 112, true),
    ('bba00c5f-e35e-466c-b28f-b5b0d8eb124b', 'Conceito Surreal', 'Conceito Surreal', 'surreal-concept', 'Arte 3D conceitual/abstrata que representa problema ou solução de forma surreal. Escultura de água, formas impossíveis, metáforas visuais.', 'Surreal 3D conceptual art that represents a concept through abstract or impossible imagery. Sculptural forms, water bodies, melting objects, impossible physics. The image should be visually striking and metaphorical - representing an idea through artistic abstraction rather than literal depiction. High-quality 3D render with artistic lighting. Think museum sculpture meets advertising.', '{"styles": ["water-sculpture", "melting-forms", "impossible-geometry", "organic-abstract"], "concept": "surreal-concept", "composition": {"style": "conceptual-3d", "layout": "centered-art", "main_element": "Surreal sculptural form"}, "requirements": ["3D rendered art", "surreal/impossible elements", "metaphorical representation", "artistic lighting", "museum quality"], "visual_description": "Abstract 3D conceptual sculpture"}'::jsonb, '🎭', 'universal', 'generic', '["generic","health","financial","ecommerce"]'::jsonb, NULL, 113, true),
    ('f1c48fd3-eaf3-4bc8-9c93-2efd19f5c340', 'Whiteboard / Quadro', 'Whiteboard / Quadro', 'whiteboard-explainer', 'Pessoa explicando algo com quadro branco e markers. Estilo educacional/tutorial que ativa viés de aprendizado.', 'Person explaining something using a whiteboard or flip chart with handwritten diagrams and text. Educational tutorial setting with markers, drawings, and annotations. The presenter can be pointing at the board or writing on it. Activates learning bias from educational contexts. Feels like getting insider knowledge or a personal lesson.', '{"concept": "whiteboard-explainer", "psychology": "learning-bias-activation", "composition": {"style": "educational-tutorial", "layout": "presenter-and-board", "main_element": "Whiteboard with handwritten content"}, "requirements": ["whiteboard or flipchart", "handwritten diagrams", "presenter visible", "marker drawings", "educational feel"], "visual_description": "Person with whiteboard explaining"}'::jsonb, '📋', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 114, true),
    ('1914bb7d-7b2f-4c18-976f-92175c363300', 'Visual de Sintoma', 'Visual de Sintoma', 'symptom-visual', 'Foca em sintomas específicos que o público experiencia (mãos inchadas, olheiras, barriga) ao invés de transformações genéricas. Reconhecimento imediato.', 'Close-up visual of a specific physical symptom that the target audience experiences. Swollen hands, tired eyes, bloated belly, skin conditions - the symptom IS the creative. Creates immediate recognition and stops scroll through relatable discomfort. Not a generic transformation, but the specific pain point made visible. Authentic, not stock photo aesthetic.', '{"concept": "symptom-visual", "examples": ["swollen_hands", "tired_eyes", "bloated_belly", "skin_condition", "joint_pain"], "composition": {"style": "authentic-medical", "layout": "close-up-focus", "main_element": "Visible symptom detail"}, "requirements": ["specific symptom visible", "close-up framing", "authentic feel", "relatable discomfort", "not stock photo"], "visual_description": "Close-up of specific symptom"}'::jsonb, '👁️', 'universal', 'generic', '["generic","health"]'::jsonb, NULL, 115, true),
    ('931d911e-5283-442b-bb50-19ed5f3f837a', 'Lifestyle de Luxo', 'Lifestyle de Luxo', 'luxury-lifestyle', 'Aspiracional premium: champagne, banheira, yacht, vistas panorâmicas. Status comparison trigger para produtos premium.', 'Aspirational luxury lifestyle imagery. Champagne, luxury bathtub, yacht deck, penthouse views, designer interiors, private jets. The product integrates naturally into an aspirational scene that triggers status comparison. Premium lighting, high production value, effortless elegance. Sells the lifestyle and identity, not just the product.', '{"concept": "luxury-lifestyle", "settings": ["yacht", "penthouse", "spa", "private_jet", "designer_home", "rooftop"], "composition": {"style": "premium-aspirational", "layout": "lifestyle-integration", "main_element": "Luxury environment with product"}, "requirements": ["luxury setting", "premium lighting", "effortless elegance", "status signals", "product integration"], "visual_description": "Premium aspirational lifestyle scene"}'::jsonb, '✨', 'universal', 'generic', '["generic","financial","ecommerce"]'::jsonb, NULL, 116, true),
    ('38742230-f3dc-494c-9be9-0b074dfed1a7', 'Unboxing / Avalanche', 'Unboxing / Avalanche', 'unboxing-avalanche', 'Produtos se acumulando durante unboxing. Value shock visual mostrando abundância e acessibilidade sem produção polida.', 'Unboxing scene with multiple products accumulating and stacking up. The visual shows abundance and value - many items revealed one after another creating a pile or avalanche of products. Casual, authentic unboxing aesthetic, not polished studio photography. Creates perceived value through quantity visualization. The shock of how much you get.', '{"concept": "unboxing-avalanche", "psychology": "perceived-value-through-quantity", "composition": {"style": "value-shock", "layout": "unboxing-scene", "main_element": "Multiple products accumulating"}, "requirements": ["multiple products visible", "unboxing context", "abundance feel", "casual aesthetic", "value visualization"], "visual_description": "Products stacking during unboxing"}'::jsonb, '📦', 'universal', 'generic', '["generic","ecommerce"]'::jsonb, NULL, 117, true),
    ('7778e894-fa5c-43f4-a497-55fdcc3aa5bb', 'Painéis de Quadrinho', 'Painéis de Quadrinho', 'comic-panels', 'Ilustração em 4 painéis estilo tirinha/quadrinhos simples. Micro-história visual com setup, tensão e resolução.', 'Simple 4-panel comic strip or sequential illustration telling a micro-story. Setup, problem, discovery, resolution format. Clean, minimal illustration style - not complex manga, more like simple flat illustrations or line drawings. Each panel advances the narrative. The format is familiar and engaging, pulling viewers through the story to the resolution where the product appears.', '{"concept": "comic-panels", "narrative": ["panel1_setup", "panel2_problem", "panel3_discovery", "panel4_resolution"], "composition": {"style": "simple-illustration", "layout": "2x2-grid", "main_element": "Sequential comic panels"}, "requirements": ["4 sequential panels", "simple illustration style", "clear narrative arc", "setup-problem-solution", "product in resolution"], "visual_description": "4-panel comic strip illustration"}'::jsonb, '🎬', 'universal', 'generic', '["generic","health","jobs","ecommerce"]'::jsonb, NULL, 118, true),
    ('60f8fbc0-951d-4d65-8d56-a192304f9467', 'Print de Podcast', 'Print de Podcast', 'podcast-screenshot', 'Screenshot de episódio de podcast com legenda/quote. Pode ser imagem única ou duas cenas (host + convidado) com falas diferentes.', 'Screenshot that looks like a frame from a video podcast episode. Shows one or two people (host and guest) with caption text overlay showing what they are saying. Can be single frame or split into two scenes for dialogue effect. Podcast studio aesthetic with microphones visible. The quote/caption IS the ad copy. Feels like catching an interesting moment from a real podcast.', '{"concept": "podcast-screenshot", "variations": ["single_speaker", "host_and_guest", "split_dialogue", "reaction_moment"], "composition": {"style": "podcast-studio", "layout": "single-frame-or-split", "main_element": "Podcast speakers with quote overlay"}, "requirements": ["podcast studio setting", "microphones visible", "caption/quote text", "conversational feel", "authentic moment"], "visual_description": "Podcast episode frame with caption"}'::jsonb, '🎙️', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 119, true),
    ('930a0657-a6ef-44e8-a60e-59bdb53597bb', 'Print de Comentários', 'Print de Comentários', 'social-comments', 'Screenshot de comentários de redes sociais ou reviews de e-commerce elogiando o produto. Prova social em formato nativo.', 'Screenshot showing comments from social media (Instagram, Facebook, TikTok) or e-commerce reviews (Amazon, Mercado Livre style) praising the product. Multiple positive comments visible, with usernames, profile pictures, likes, and timestamps. Combines social proof with native platform formatting. Looks like organic user-generated praise, not advertising.', '{"concept": "social-comments", "platforms": ["instagram", "facebook", "tiktok", "amazon_reviews", "google_reviews"], "composition": {"style": "native-social-interface", "layout": "comment-thread", "main_element": "Multiple positive comments"}, "requirements": ["multiple comments", "usernames and avatars", "likes/reactions", "positive testimonials", "platform-native UI"], "visual_description": "Social media comments screenshot"}'::jsonb, '💭', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 123, true),
    ('f5580240-8455-454b-ba03-fa7d1add95a4', 'Meme / Humor Nativo', 'Meme / Humor Nativo', 'meme-humor', 'Formatos de meme populares adaptados ao produto. Parece conteúdo orgânico de entretenimento com alto potencial de compartilhamento.', 'Popular meme format adapted to promote the product. Uses recognizable meme templates (reaction images, comparison memes, relatable situations) with text that relates to the product benefit or problem it solves. Looks like organic entertainment content, not advertising. The humor should feel natural, not forced. High shareability potential.', '{"concept": "meme-humor", "formats": ["reaction_image", "comparison_meme", "expectation_vs_reality", "nobody_meme", "drake_format"], "composition": {"style": "internet-humor", "layout": "meme-format", "main_element": "Meme template with custom text"}, "requirements": ["recognizable meme format", "relatable humor", "product connection", "shareable", "not forced"], "visual_description": "Popular meme format with product angle"}'::jsonb, '😂', 'universal', 'generic', '["generic","jobs","ecommerce"]'::jsonb, NULL, 124, true),
    ('2401dd59-a1e6-49f3-b86b-516a055f13b8', 'Print de Resultado', 'Print de Resultado', 'dashboard-result', 'Screenshot de dashboard de analytics, extrato bancário, painel de vendas, resultado de exame. Prova visual de que o método funciona.', 'Screenshot showing impressive results - analytics dashboard, bank statement, sales panel, medical test results, or any metrics display. The numbers and graphs tell the success story visually. Feels like proof that the method or product actually works. Can include partial blur or redaction for authenticity. Results should be impressive but believable.', '{"types": ["analytics_dashboard", "bank_statement", "sales_report", "health_metrics", "growth_chart"], "concept": "dashboard-result", "composition": {"style": "proof-screenshot", "layout": "analytics-interface", "main_element": "Dashboard with impressive metrics"}, "requirements": ["visible metrics/numbers", "dashboard UI", "impressive results", "believable data", "proof of success"], "visual_description": "Results dashboard or metrics screenshot"}'::jsonb, '📊', 'universal', 'generic', '["generic","financial","jobs","health"]'::jsonb, NULL, 125, true),
    ('6e650ab9-1b8b-4053-a185-aa84b40e1e61', 'Narrativo Sequencial', 'Narrativo Sequencial', 'story-sequence', 'Cards que contam uma jornada como tirinha digital: setup, tensão, payoff. Prende o usuário com micro-história até o CTA.', 'Sequential story cards that tell a journey like a digital comic strip. Each card or panel reveals part of a narrative: setup introduces the situation, tension shows the problem or conflict, payoff delivers the resolution with the product. Designed to hold attention through storytelling, with the CTA appearing at the story climax.', '{"concept": "story-sequence", "structure": ["card1_setup", "card2_problem", "card3_turning_point", "card4_resolution_cta"], "composition": {"style": "visual-storytelling", "layout": "carousel-or-grid", "main_element": "Story progression panels"}, "requirements": ["clear narrative arc", "setup-tension-payoff", "visual progression", "engaging story", "CTA at climax"], "visual_description": "Sequential narrative cards"}'::jsonb, '📖', 'universal', 'generic', '["generic","health","jobs","ecommerce"]'::jsonb, NULL, 126, true),
    ('b764b00b-6a3d-4c8b-a501-7c98c1925db5', 'Post Fake Orgânico', 'Post Fake Orgânico', 'fake-organic-post', 'Simula post orgânico do Instagram, Twitter/X ou TikTok com interface completa (likes, comentários, perfil). Parece print de post viral.', 'Screenshot simulating an organic social media post from Instagram, Twitter/X, or TikTok. Complete platform interface with profile picture, username, post content, likes, comments, shares, and engagement metrics. Looks like a screenshot of a viral post that someone shared. The content appears to be genuine user content, not advertising. High engagement numbers add social proof.', '{"concept": "fake-organic-post", "platforms": ["instagram_post", "twitter_tweet", "tiktok_video", "facebook_post", "linkedin_post"], "composition": {"style": "viral-screenshot", "layout": "platform-native-post", "main_element": "Social media post with full UI"}, "requirements": ["complete platform interface", "profile and username", "engagement metrics", "looks organic", "viral potential"], "visual_description": "Fake viral social media post"}'::jsonb, '📱', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 129, true),
    ('c4b620f0-c518-4819-96ab-11639e966127', 'Depoimento Cliente', 'Depoimento Cliente', 'fin-testimonial', 'Card de review com foto, citação e estrelas.', 'Financial testimonial card with customer photo, quote about loan approval, and 5-star rating. Includes name and location for authenticity. Trust badge or verified icon. Clean card design floating over gradient.', '{"concept": "testimonial", "elements": ["customer_photo", "quote", "star_rating", "verified_badge"]}'::jsonb, '⭐', 'prova_social', 'financial', '["financial"]'::jsonb, NULL, 201, true),
    ('74390054-f470-4f6b-8f87-cd292632b109', 'Números Impactantes', 'Números Impactantes', 'fin-numbers', 'Estatísticas grandes: "50.000+ aprovações", "+R$100M liberados".', 'Large impactful numbers dominating the creative. Statistics like "50,000+ approvals", "R$100M+ released", "98% satisfaction". Numbers are extra-large and eye-catching. Professional financial design.', '{"style": "extra-large", "concept": "numbers", "elements": ["stat_number", "description", "currency_symbol"]}'::jsonb, '📊', 'prova_social', 'financial', '["financial"]'::jsonb, NULL, 202, true),
    ('2fd715b4-96ed-429a-b5a2-5f2ac3aaabe1', 'Comunidade / Muitos Aprovados', 'Comunidade / Muitos Aprovados', 'fin-community', 'Múltiplas pessoas/avatares representando muitos clientes.', 'Visual showing community of approved customers. Multiple profile pictures, avatars, or silhouettes. Counter showing "X people already approved". Sense of belonging and social validation.', '{"concept": "community", "elements": ["multiple_avatars", "counter", "social_proof_text"]}'::jsonb, '👥', 'prova_social', 'financial', '["financial"]'::jsonb, NULL, 203, true),
    ('5c00f98b-714f-4f68-a067-472241327567', 'Selos de Confiança', 'Selos de Confiança', 'fin-trust-badges', 'Badges de parceiros, certificações, segurança.', 'Trust badges and security seals prominently displayed. Bank partner logos, SSL security, regulated institution badge, BBB rating. Professional arrangement that builds confidence.', '{"concept": "trust-badges", "elements": ["partner_logos", "security_seal", "certification_badge"]}'::jsonb, '🛡️', 'prova_social', 'financial', '["financial"]'::jsonb, NULL, 204, true),
    ('eb48c4d3-acee-4a96-b388-21deec7a9241', 'Banner Hero Premium', 'Banner Hero Premium', 'banner-hero-premium', 'Banner com visual premium, headline forte e composição hero.', 'Premium hero banner layout with a bold headline, a strong subhead, and a central hero visual. Clean grid, generous spacing, brand-quality polish. Large CTA button only if specified. Use elegant sans-serif typography (e.g., Inter/SF Pro/Helvetica Neue) with clear hierarchy and high contrast.', '{"concept": "banner-hero-premium", "typography": {"font_style": "Elegant sans-serif (Inter/SF Pro/Helvetica Neue), strong hierarchy"}, "composition": {"style": "premium", "layout": "hero-grid", "main_element": "Hero visual + headline"}, "requirements": ["headline dominance", "brand-quality polish", "clean grid", "high contrast"], "visual_description": "Premium hero banner with bold headline and hero visual"}'::jsonb, '🏆', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 224, true),
    ('89ed0d1f-abf2-4fbb-a57c-4c74e4e6fbe6', 'Banner Oferta + Benefícios', 'Banner Oferta + Benefícios', 'banner-offer-stack', 'Headline + oferta + lista de benefícios. Layout vendedor.', 'Offer-driven banner with a bold headline, a clear offer block, and a short stacked list of benefits. Emphasize clarity and scanability. Large CTA button only if specified. Use a bold display font for the headline (Bebas Neue/Anton) and a clean sans for body (Inter/Source Sans).', '{"concept": "banner-offer-stack", "typography": {"font_style": "Display headline (Bebas/Anton) + clean body (Inter/Source Sans)"}, "composition": {"style": "conversion", "layout": "stacked", "main_element": "Offer block with benefits list"}, "requirements": ["offer block", "benefit bullets", "clear hierarchy", "high contrast"], "visual_description": "Headline + offer block + benefits stack"}'::jsonb, '🧾', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 225, true),
    ('658b5b00-9cc2-4faa-9843-5d1e2ca8cb44', 'Banner Carta Aberta', 'Banner Carta Aberta', 'banner-open-letter', 'Estilo carta aberta com callout direto ao público.', 'Open-letter style banner with a direct callout to a specific audience. Typography-forward layout with a letter-like structure, subtle paper texture, and a bold headline. No CTA unless explicitly provided. Use classic serif for the headline (Georgia/Times) and clean sans for body (Inter).', '{"concept": "banner-open-letter", "typography": {"font_style": "Serif headline (Georgia/Times) + clean sans body (Inter)"}, "composition": {"style": "direct-response", "layout": "editorial-letter", "main_element": "Letter-style text block"}, "requirements": ["callout headline", "letter structure", "text-forward", "no CTA unless specified"], "visual_description": "Open-letter style layout with direct callout"}'::jsonb, '✉️', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 226, true),
    ('6f9fad31-dc38-470b-b608-f942a8056d1f', 'Banner Reason-Why', 'Banner Reason-Why', 'banner-reason-why', 'Explica POR QUE funciona, com mini-blocos de argumentos.', 'Reason-why banner that explains why the product works. Use short argument blocks with clear labels, combining emotional and factual cues. Large CTA button only if specified. Use a modern serif for headings (Playfair) and a clean sans for body (Inter/Source Sans).', '{"concept": "banner-reason-why", "typography": {"font_style": "Modern serif headings (Playfair) + clean sans body (Inter)"}, "composition": {"style": "educational", "layout": "modular", "main_element": "Why-it-works blocks"}, "requirements": ["clear labels", "short blocks", "credible tone", "high legibility"], "visual_description": "Reason-why explanation blocks"}'::jsonb, '🧠', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 227, true),
    ('904018e7-e1e4-410e-8f0f-0fd6e423cfd9', 'Banner Claim Ultra-Específico', 'Banner Claim Ultra-Específico', 'banner-ultra-specific-claim', 'Headline com número específico e detalhe memorável.', 'Ultra-specific claim banner with a single precise statement (numbers + specific detail). Minimal supporting elements, maximum credibility. No CTA unless specified. Use bold sans-serif (Montserrat/Helvetica Neue) with oversized numerals.', '{"concept": "banner-ultra-specific-claim", "typography": {"font_style": "Bold sans (Montserrat/Helvetica Neue) with oversized numerals"}, "composition": {"style": "credible", "layout": "minimal", "main_element": "Claim headline + numeric proof"}, "requirements": ["specific numbers", "minimal elements", "credibility", "high contrast"], "visual_description": "Single precise claim with numeric proof"}'::jsonb, '🎯', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 228, true),
    ('9b30d0d3-c625-4fb4-b14e-474371bcc330', 'Banner Honestidade Radical', 'Banner Honestidade Radical', 'banner-honest-confession', 'Começa com uma confissão honesta sobre um defeito.', 'Honest confession banner: start with a drawback or surprising truth, then pivot to the benefit. Text-forward with strong hierarchy. No CTA unless specified. Use clean, legible sans-serif (Inter/Roboto) and emphasize the first line.', '{"concept": "banner-honest-confession", "typography": {"font_style": "Clean sans (Inter/Roboto) with emphasized first line"}, "composition": {"style": "authentic", "layout": "text-forward", "main_element": "Confession headline + pivot"}, "requirements": ["honest opening line", "clear pivot", "high legibility"], "visual_description": "Honest drawback then benefit"}'::jsonb, '🫱', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 229, true),
    ('07f59110-8aa9-4509-b86c-54c215ff2564', 'Banner Story Lead', 'Banner Story Lead', 'banner-story-lead', 'Lead de história curta com tensão e virada.', 'Story-lead banner with a short, dramatic setup and a payoff line. Emphasize narrative flow and emotional contrast. No CTA unless specified. Use a readable serif for narrative (Georgia/Times) and bold sans for the hook.', '{"concept": "banner-story-lead", "typography": {"font_style": "Readable serif narrative (Georgia/Times) + bold sans hook"}, "composition": {"style": "story-driven", "layout": "narrative-block", "main_element": "Story lead text"}, "requirements": ["hook line", "short narrative", "clear payoff"], "visual_description": "Short story lead with tension and payoff"}'::jsonb, '📖', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 230, true),
    ('a0523e5d-5d7c-4f4e-ba11-a6bcf1a2a165', 'Banner Secret Lead', 'Banner Secret Lead', 'banner-secret-lead', 'Formato "segredo" para curiosidade máxima.', 'Secret-lead banner that hints at a hidden advantage or technique. Curiosity-forward headline, minimal supporting text. No CTA unless specified. Use a bold condensed display font (Anton/Oswald) and minimal supporting text.', '{"concept": "banner-secret-lead", "typography": {"font_style": "Condensed display (Anton/Oswald) with minimal support text"}, "composition": {"style": "mystery", "layout": "headline-dominant", "main_element": "Curiosity headline"}, "requirements": ["curiosity hook", "minimal support text", "strong contrast"], "visual_description": "Secret/curiosity headline"}'::jsonb, '🗝️', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 231, true),
    ('3aab34cd-fa01-4901-9040-40757dab3515', 'Banner Bullets de Benefício', 'Banner Bullets de Benefício', 'banner-bullet-stack', 'Lista de benefícios em bullets de alta legibilidade.', 'Benefit-bullets banner with 4–6 concise bullet points. Strong headline, clear list structure, easy scanning. Large CTA only if specified. Use a bold sans headline and a clean mono or sans for bullets.', '{"concept": "banner-bullet-stack", "typography": {"font_style": "Bold sans headline + clean sans/mono bullets"}, "composition": {"style": "direct-response", "layout": "list-focused", "main_element": "Bulleted benefits"}, "requirements": ["short bullets", "clear hierarchy", "scan-friendly"], "visual_description": "Benefit bullets list"}'::jsonb, '•', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 232, true),
    ('98185f7a-2906-4645-b74d-2e427370ca7a', 'Banner Prova de Valor', 'Banner Prova de Valor', 'banner-proof-of-value', 'Compara valor/custo com alternativa.', 'Proof-of-value banner comparing cost or value against alternatives. Use clear comparison blocks, numeric emphasis, and a strong conclusion line. No CTA unless specified. Use bold numerals and clean typography.', '{"concept": "banner-proof-of-value", "typography": {"font_style": "Bold numerals + clean sans text"}, "composition": {"style": "credible", "layout": "comparison-blocks", "main_element": "Value comparison blocks"}, "requirements": ["numeric emphasis", "clear contrast", "credible tone"], "visual_description": "Value comparison with numeric emphasis"}'::jsonb, '💡', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 233, true),
    ('f8467dd4-55c7-442a-b01c-6112ab2c65b5', 'Banner Minimal Sem CTA', 'Banner Minimal Sem CTA', 'banner-minimal-no-cta', 'Banner minimalista com headline e subtexto, sem botão.', 'Minimal banner with a bold headline and short subtext only. No CTA button. Clean negative space, strong typography, premium restraint. Use modern sans-serif (Inter/SF Pro) and subtle accent line.', '{"concept": "banner-minimal-no-cta", "typography": {"font_style": "Modern sans (Inter/SF Pro), high contrast"}, "composition": {"style": "restrained", "layout": "minimal", "main_element": "Headline + subtext"}, "requirements": ["no CTA", "strong typography", "clean negative space"], "visual_description": "Minimal headline + subtext, no CTA"}'::jsonb, '⬜', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 234, true),
    ('b8670225-20f0-4ec9-ac7b-d3b69fce061e', 'Banner Editorial Luxury', 'Banner Editorial Luxury', 'banner-editorial-luxury', 'Banner editorial com sensação premium e tipografia elegante.', 'Luxury editorial banner with magazine-like composition, refined spacing, and elegant typography. Subtle textures, soft lighting, premium aesthetic. Large CTA only if specified. Use serif headline (Didot/Playfair) + clean sans body.', '{"concept": "banner-editorial-luxury", "typography": {"font_style": "Serif headline (Didot/Playfair) + clean sans body"}, "composition": {"style": "luxury", "layout": "magazine", "main_element": "Editorial headline + hero visual"}, "requirements": ["refined spacing", "premium texture", "editorial feel"], "visual_description": "Luxury editorial magazine-style banner"}'::jsonb, '🖤', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 235, true),
    ('0bf6a5cf-c2e2-466e-a4ba-fec50c81ff7a', 'Camera Roll / Photo Dump', 'Camera Roll / Photo Dump', 'native-camera-roll', 'Colagem de fotos estilo "camera roll".', 'Camera roll / photo dump collage with multiple casual photos, timestamp overlays, and native phone UI cues. Looks like a real gallery screenshot shared by a friend.', '{"concept": "native-camera-roll", "composition": {"style": "native-ui", "layout": "gallery-grid", "main_element": "multi-photo grid"}, "requirements": ["multiple photos", "timestamp cues", "gallery UI feel", "organic look"], "visual_description": "Phone gallery photo dump collage"}'::jsonb, '🖼️', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 236, true),
    ('4038f572-2dd4-4d8a-b884-6fd085b6557d', 'Story Frame Nativo', 'Story Frame Nativo', 'native-story-frame', 'Frame de story com barras e UI nativa.', 'Instagram/TikTok story frame screenshot with native UI bars, subtle icons, and a vertical composition. Feels like an organic story capture, not a designed ad.', '{"concept": "native-story-frame", "composition": {"style": "native-ui", "layout": "vertical-frame", "main_element": "story frame"}, "requirements": ["story UI bars", "vertical frame", "organic feel"], "visual_description": "Native story UI frame"}'::jsonb, '📱', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 237, true),
    ('12de8961-23ce-4be1-a8b4-2f1ba22fde02', 'Thread de Fórum/Reddit', 'Thread de Fórum/Reddit', 'native-forum-thread', 'Screenshot de thread estilo fórum com respostas.', 'Forum or Reddit-style thread screenshot with a question and multiple replies. Upvotes, usernames, and nested replies for social proof. Feels like authentic community discussion.', '{"concept": "native-forum-thread", "composition": {"style": "native-ui", "layout": "feed-thread", "main_element": "thread + replies"}, "requirements": ["thread title", "nested replies", "upvote UI", "authentic look"], "visual_description": "Forum thread screenshot with replies"}'::jsonb, '🧵', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 238, true),
    ('fa0135d0-3bda-4497-9c21-283b9745b46d', 'Checklist Nativa', 'Checklist Nativa', 'native-checklist', 'Checklist tipo app de tarefas, com itens marcados.', 'Checklist-style screenshot resembling a notes or tasks app. Simple list with checkmarks, clean UI, and a personal feel. Looks like someone sharing their checklist.', '{"concept": "native-checklist", "composition": {"style": "native-ui", "layout": "list", "main_element": "checklist items"}, "requirements": ["checkmarks", "simple list", "native app feel", "personal tone"], "visual_description": "Checklist app screenshot"}'::jsonb, '✅', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 239, true),
    ('73819cc9-7075-4808-94cc-f9f3f8e18394', 'Simulador / Calculadora', 'Simulador / Calculadora', 'fin-simulator', 'Interface de app mostrando simulação de valores e parcelas.', 'Loan simulator UI showing interactive value selection. Slider for amount, installment options, monthly payment preview. Clean fintech app design. The UI IS the product - looks like real app screenshot.', '{"concept": "simulator", "elements": ["amount_slider", "installment_options", "payment_preview"]}'::jsonb, '🧮', 'produto', 'financial', '["financial"]'::jsonb, NULL, 301, true),
    ('a8e24909-05cb-4083-b21c-55fa77f5a285', 'App no Smartphone', 'App no Smartphone', 'fin-smartphone', 'Mockup de celular mostrando o app de empréstimo.', 'Smartphone mockup showing loan app interface. Modern device angle, clean app UI visible on screen. Focus on ease of use and mobile accessibility. Professional product shot feel.', '{"concept": "smartphone-mockup", "elements": ["phone_device", "app_interface", "modern_angle"]}'::jsonb, '📱', 'produto', 'financial', '["financial"]'::jsonb, NULL, 302, true),
    ('825ac801-43d4-4046-83bc-2ade612654b9', 'Lista de Features', 'Lista de Features', 'fin-features', 'Bullets com ícones: ✓ Sem burocracia ✓ 100% online ✓ Dinheiro rápido.', 'Feature list with checkmark icons. Benefits like: No bureaucracy, 100% online, Fast money, Low rates. Clean vertical list, checkmark or tick icons, readable text. Professional layout.', '{"layout": "checklist", "concept": "features", "elements": ["checkmarks", "benefit_text", "icons"]}'::jsonb, '✅', 'produto', 'financial', '["financial"]'::jsonb, NULL, 303, true),
    ('c0729b4b-faac-46ce-9502-75f90a75a5bb', 'Comparação Tradicional vs Digital', 'Comparação Tradicional vs Digital', 'fin-comparison', 'Banco tradicional vs nosso app: filas vs conforto de casa.', 'Side-by-side comparison: Traditional bank (queues, paperwork, waiting) vs Digital solution (couch, phone, instant). Visual contrast showing the modern advantage. Professional split design.', '{"left": "traditional_bank", "right": "digital_solution", "concept": "comparison", "elements": ["queue_image", "home_comfort"]}'::jsonb, '⚔️', 'produto', 'financial', '["financial"]'::jsonb, NULL, 304, true),
    ('c1ac0197-faf2-48f3-844f-5688080488eb', 'Passos Simples', 'Passos Simples', 'fin-steps', '1-2-3 visual steps mostrando facilidade do processo.', 'Simple numbered steps showing easy process. 1: Fill form. 2: Wait for approval. 3: Receive money. Clean icons for each step, numbered badges, progress indication. Maximum simplicity.', '{"count": 3, "concept": "steps", "elements": ["step_numbers", "icons", "short_descriptions"]}'::jsonb, '1️⃣', 'produto', 'financial', '["financial"]'::jsonb, NULL, 305, true),
    ('9a6b12f2-6f67-46c3-98a4-524673e68687', 'Thumbnail de Vídeo', 'Thumbnail de Vídeo', 'video-thumbnail', 'Imagem que parece preview de vídeo com play button. Simula conteúdo de vídeo para aumentar CTR drasticamente.', 'Image that looks like a video thumbnail with a prominent play button overlay. The composition should suggest movement or action frozen in time. Include a large, semi-transparent play button (triangle in circle) centered or slightly off-center. The image beneath should be engaging and suggest there is valuable video content to watch. Can include duration timestamp in corner (e.g., "3:42"). High contrast, compelling freeze-frame aesthetic.', '{"concept": "video-thumbnail", "elements": ["play_button_overlay", "compelling_image", "duration_badge", "progress_bar"], "psychology": "video-content-curiosity", "composition": {"style": "youtube-thumbnail", "layout": "video-preview", "main_element": "Engaging freeze-frame with play button"}, "requirements": ["prominent play button", "engaging freeze-frame", "suggests motion", "optional duration timestamp", "high contrast"], "visual_description": "Video preview with play button overlay"}'::jsonb, '▶️', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 340, true),
    ('1f29ea1c-62d5-49fc-a94a-680bd764e844', 'Ingrediente Hero', 'Ingrediente Hero', 'ingredient-hero', 'Um ingrediente em destaque absoluto com seus benefícios. Perfeito para health, beauty, supplements. Foco em um único elemento poderoso.', 'Single powerful ingredient as the hero of the image. The ingredient (herb, vitamin, mineral, natural element) is dramatically lit and takes center stage. Clean background that makes the ingredient pop. Can include floating particles, glow effects, or scientific visualization. Surrounding text or icons hint at key benefits. Premium, scientific, yet natural aesthetic. Think supplement packaging meets editorial photography.', '{"concept": "ingredient-hero", "best_for": ["supplements", "skincare", "health_products", "natural_remedies"], "elements": ["hero_ingredient", "glow_effects", "benefit_icons", "scientific_elements"], "composition": {"style": "premium-scientific", "layout": "product-spotlight", "main_element": "Hero ingredient center stage"}, "requirements": ["single ingredient focus", "dramatic lighting", "clean background", "benefit hints", "premium feel"], "visual_description": "Single ingredient dramatically showcased"}'::jsonb, '🌿', 'universal', 'generic', '["generic","health","ecommerce"]'::jsonb, NULL, 341, true),
    ('d338af9d-74de-45cd-8795-1112f97ae09b', 'Card de Receita', 'Card de Receita', 'recipe-card', 'Formato de receita com ingredientes listados e instruções visuais. Funciona para suplementos, alimentos, até produtos não-food como "receita para sucesso".', 'Recipe card format showing ingredients list and visual instructions. Clean, organized layout like a cookbook page or recipe app. Numbered steps or ingredient list with checkboxes. Food photography or product shots integrated into the recipe format. Can be literal (actual recipe) or metaphorical (recipe for success, ingredients for results). Warm, inviting, actionable design that makes viewers want to try it.', '{"concept": "recipe-card", "elements": ["ingredients_list", "step_numbers", "food_or_product_photo", "checkboxes", "serving_info"], "variations": ["literal_recipe", "metaphorical_recipe", "ingredients_only", "full_instructions"], "composition": {"style": "cookbook-app", "layout": "recipe-card", "main_element": "Recipe layout with list and visuals"}, "requirements": ["ingredient list", "numbered steps or process", "visual elements", "actionable format", "warm inviting feel"], "visual_description": "Recipe format with ingredients and steps"}'::jsonb, '📜', 'universal', 'generic', '["generic","health","ecommerce"]'::jsonb, NULL, 342, true),
    ('fbb61a13-d813-4df5-882b-92f77825c9a6', 'Cara de Reação', 'Cara de Reação', 'reaction-face', 'Rosto com expressão forte (surpresa, choque, alegria) estilo thumbnail de YouTube/TikTok. Expressões humanas são impossíveis de ignorar.', 'Close-up of a face showing strong emotional reaction - surprise, shock, excitement, disbelief, or joy. YouTube/TikTok thumbnail style where the facial expression tells the story. Eyes wide, mouth open, exaggerated but authentic emotion. The face should fill most of the frame. Can include emoji overlays or text hints about what caused the reaction. Human faces with strong emotions are psychologically impossible to ignore in a feed.', '{"concept": "reaction-face", "emotions": ["surprise", "shock", "excitement", "disbelief", "joy", "amazement"], "psychology": "facial-recognition-priority", "composition": {"style": "youtube-reaction", "layout": "close-up-portrait", "main_element": "Expressive face filling frame"}, "requirements": ["strong facial expression", "face fills frame", "authentic emotion", "high energy", "attention-grabbing"], "visual_description": "Close-up face with strong emotional reaction"}'::jsonb, '😲', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 343, true),
    ('f1c40205-83e8-4a76-a2e2-2cb552b231fb', 'Reação Split Screen', 'Reação Split Screen', 'split-reaction', 'Duas reações lado a lado: antes de usar vs depois de usar, ou expectativa vs realidade. Contraste emocional em uma imagem.', 'Split screen showing two contrasting emotional reactions side by side. Left side shows negative emotion (frustration, confusion, disappointment, exhaustion) and right side shows positive emotion (relief, joy, confidence, energy). Same person or different people. Clear visual contrast between the two states. Can include labels like "Before" / "After" or "Expectation" / "Reality" or "Without X" / "With X". The emotional journey is immediately clear.', '{"labels": ["before_after", "expectation_reality", "without_with", "old_new"], "concept": "split-reaction", "composition": {"style": "reaction-comparison", "layout": "side-by-side-split", "main_element": "Split screen emotional contrast"}, "requirements": ["two contrasting emotions", "clear split", "same or different people", "labels optional", "obvious transformation"], "left_emotions": ["frustration", "confusion", "disappointment", "exhaustion", "stress"], "right_emotions": ["relief", "joy", "confidence", "energy", "satisfaction"], "visual_description": "Two contrasting reactions side by side"}'::jsonb, '😫➡️😊', 'universal', 'generic', '["generic","financial","jobs","health","ecommerce"]'::jsonb, NULL, 344, true),
    ('60e3513a-a6ce-4cad-8347-870b5e766e90', 'Pergunta Provocadora', 'Pergunta Provocadora', 'fin-question', 'Pergunta GRANDE que fala com a dor financeira.', 'Giant provocative question about financial pain point. Questions like "Need money urgently?", "Bills piling up?", "Want a loan?". Typography-dominant, question IS the creative. High impact.', '{"style": "typography-dominant", "concept": "question", "elements": ["large_question", "question_mark"]}'::jsonb, '❓', 'curiosidade', 'financial', '["financial"]'::jsonb, NULL, 401, true),
    ('8de0feb5-d200-45ef-ad4c-7724cd13e748', 'Reveal / Descoberta', 'Reveal / Descoberta', 'fin-reveal', 'Efeito de revelar: "Descubra quanto você pode pegar".', 'Reveal or discovery moment. Text like "Discover how much you can get". Partial reveal effect, curiosity-inducing design. Sense of something being uncovered or discovered.', '{"concept": "reveal", "elements": ["reveal_text", "partial_hidden", "discovery_feeling"]}'::jsonb, '🔍', 'curiosidade', 'financial', '["financial"]'::jsonb, NULL, 402, true),
    ('c1e28cc5-1983-4387-843b-ba6e03e5be7a', 'Notificação de Celular', 'Notificação de Celular', 'fin-notification', 'Estilo notificação: "Sua simulação está pronta" ou "Você foi pré-aprovado".', 'Phone notification style creative. Notification bubble showing "Your simulation is ready" or "You are pre-approved". Looks like actual phone notification. Native, organic feel.', '{"style": "phone-native", "concept": "notification", "elements": ["notification_bubble", "app_icon", "message_text"]}'::jsonb, '🔔', 'curiosidade', 'financial', '["financial"]'::jsonb, NULL, 403, true),
    ('7f44973b-8042-44fb-9b5f-cedbb9642fa8', 'Listicle / Top X', 'Listicle / Top X', 'fin-listicle', '"5 motivos para...", "3 vantagens de...".', 'Listicle format with numbered points. "5 reasons to apply now", "3 advantages of our loan". Numbered list with eye-catching design. Each point short and impactful.', '{"concept": "listicle", "elements": ["numbered_points", "short_descriptions", "visual_hierarchy"]}'::jsonb, '📋', 'curiosidade', 'financial', '["financial"]'::jsonb, NULL, 404, true),
    ('fc67118a-7323-4d3c-a103-189c69b51021', 'Mito vs Realidade', 'Mito vs Realidade', 'fin-myth-reality', 'Desmistificando crenças sobre empréstimo.', 'Myth vs Reality format debunking loan misconceptions. Myth: "Loans are complicated" Reality: "3 simple steps". X mark for myth, checkmark for reality. Educational, trust-building.', '{"concept": "myth-reality", "elements": ["myth_statement", "reality_statement", "x_and_check_icons"]}'::jsonb, '💡', 'curiosidade', 'financial', '["financial"]'::jsonb, NULL, 405, true),
    ('91edc761-2e39-4e64-87ab-c5007540425f', 'Estatística Chocante', 'Estatística Chocante', 'fin-statistic', 'Dado estatístico que prende atenção: "8 em 10 brasileiros...".', 'Shocking statistic that grabs attention. "8 out of 10 Brazilians..." or "Only 15% know that...". Large number dominating, supporting text below. Data-driven hook.', '{"concept": "statistic", "elements": ["large_stat", "context_text", "source_optional"]}'::jsonb, '📈', 'curiosidade', 'financial', '["financial"]'::jsonb, NULL, 406, true),
    ('6b23c741-98c9-4805-9d10-cd497468e68b', 'Editorial Premium', 'Editorial Premium', 'fin-editorial', 'Estilo revista financeira de alto padrão.', 'Premium editorial style like high-end financial magazine. Sophisticated typography, generous whitespace, premium photography or graphics. Luxury feel without being flashy.', '{"style": "premium-magazine", "concept": "editorial", "elements": ["sophisticated_type", "whitespace", "premium_imagery"]}'::jsonb, '📰', 'estilo_visual', 'financial', '["financial"]'::jsonb, NULL, 501, true),
    ('7dab9302-60e8-4804-88dc-9f394a9619be', 'Cartoon / Ilustração', 'Cartoon / Ilustração', 'fin-cartoon', 'Estilo ilustrado friendly e acessível.', 'Cartoon or illustration style, friendly and approachable. Flat design characters, playful colors, accessible feel. Not childish but warm and inviting.', '{"style": "flat-friendly", "concept": "cartoon", "elements": ["illustrated_characters", "playful_colors"]}'::jsonb, '🎨', 'estilo_visual', 'financial', '["financial"]'::jsonb, NULL, 502, true),
    ('92e6ebe1-82c1-4d57-b515-1e369641264d', 'Colagem / Mixed Media', 'Colagem / Mixed Media', 'fin-collage', 'Elementos misturados: fotos + ilustrações + textos.', 'Mixed media collage combining photos, illustrations, and text elements. Creative layering, modern editorial approach. Visual interest through variety of elements.', '{"concept": "collage", "elements": ["photos", "illustrations", "text_overlays", "layered_design"]}'::jsonb, '🖼️', 'estilo_visual', 'financial', '["financial"]'::jsonb, NULL, 503, true),
    ('d2f59b47-ba0f-4532-b90f-1d479debff65', '3D / Isométrico', '3D / Isométrico', 'fin-3d', 'Elementos 3D ou isométricos modernos.', '3D or isometric style elements. Modern 3D icons, isometric money, floating cards. Tech-forward, contemporary feel. Clean rendering, soft shadows.', '{"style": "isometric-modern", "concept": "3d", "elements": ["3d_icons", "isometric_elements", "floating_objects"]}'::jsonb, '🧊', 'estilo_visual', 'financial', '["financial"]'::jsonb, NULL, 504, true),
    ('fba7789e-d621-46c1-b707-d77049b9764c', 'Glassmorphism / UI Moderno', 'Glassmorphism / UI Moderno', 'fin-glassmorphism', 'Efeito vidro fosco, UI moderna com transparências.', 'Glassmorphism UI style with frosted glass effects. Modern transparency, blur effects, subtle gradients. Contemporary fintech aesthetic. Premium app feel.', '{"concept": "glassmorphism", "elements": ["frosted_glass", "blur_effects", "subtle_gradients"]}'::jsonb, '🪟', 'estilo_visual', 'financial', '["financial"]'::jsonb, NULL, 505, true),
    ('409e16e1-1007-451a-8fd7-beb5bba688bf', 'Gradientes Vibrantes', 'Gradientes Vibrantes', 'fin-gradient', 'Fundos com gradientes chamativos.', 'Vibrant gradient backgrounds. Bold color transitions, modern gradient styles. Eye-catching without overwhelming the content. Contemporary design trend.', '{"style": "vibrant", "concept": "gradient", "elements": ["bold_gradients", "color_transitions"]}'::jsonb, '🌈', 'estilo_visual', 'financial', '["financial"]'::jsonb, NULL, 506, true),
    ('e9f8629b-59c1-4c17-9d70-07d7c5f2f42c', 'Dark Mode / Escuro', 'Dark Mode / Escuro', 'fin-dark-mode', 'Fundo escuro, elementos claros, feel premium.', 'Dark mode aesthetic with dark backgrounds and light elements. Premium feel, modern tech vibe. Gold or green accents on dark. Sophisticated night mode.', '{"accents": ["gold", "green", "white"], "concept": "dark-mode", "background": "dark"}'::jsonb, '🌙', 'estilo_visual', 'financial', '["financial"]'::jsonb, NULL, 507, true),
    ('277a0121-4c6c-4dec-b027-742d646174ac', 'Minimalista', 'Minimalista', 'fin-minimal', 'Design super limpo, poucos elementos, muito espaço branco.', 'Super clean minimalist design. Few elements, lots of whitespace. Maximum clarity, zero clutter. Every element has purpose. Premium simplicity.', '{"style": "clean", "concept": "minimal", "elements": ["whitespace", "few_elements", "high_clarity"]}'::jsonb, '⬜', 'estilo_visual', 'financial', '["financial"]'::jsonb, NULL, 508, true),
    ('abc3b484-d632-4906-a19e-01c27b3e4095', 'Neon / Futurista', 'Neon / Futurista', 'fin-neon', 'Estilo neon, cores vibrantes, feel tecnológico.', 'Neon futuristic style with glowing effects. Vibrant neon colors on dark background. Tech-forward, digital native feel. Cyberpunk-lite aesthetic.', '{"style": "futuristic", "concept": "neon", "elements": ["neon_glow", "vibrant_colors", "dark_background"]}'::jsonb, '💫', 'estilo_visual', 'financial', '["financial"]'::jsonb, NULL, 509, true)
ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
    name_pt = EXCLUDED.name_pt,
    description = EXCLUDED.description,
    prompt_modifier = EXCLUDED.prompt_modifier,
    prompt_template_json = EXCLUDED.prompt_template_json,
    icon = EXCLUDED.icon,
    category = EXCLUDED.category,
    niche = EXCLUDED.niche,
    works_for_niches = EXCLUDED.works_for_niches,
    example_images = EXCLUDED.example_images,
    sort_order = EXCLUDED.sort_order,
    is_active = EXCLUDED.is_active,
    updated_at = now();

-- 6. Rename indexes
ALTER INDEX IF EXISTS idx_style_presets_active RENAME TO idx_creative_concepts_active;
ALTER INDEX IF EXISTS idx_style_presets_type RENAME TO idx_creative_concepts_type;

-- 7. Add indexes
CREATE INDEX IF NOT EXISTS idx_creative_concepts_sort ON creative_concepts(sort_order);
CREATE INDEX IF NOT EXISTS idx_creative_concepts_category ON creative_concepts(category);
CREATE INDEX IF NOT EXISTS idx_creative_concepts_niche ON creative_concepts(niche);

COMMIT;
